CREATE TABLE @temp_database_schema.rwdfeatxconcept_count_data
USING DELTA
AS
SELECT
cohort_definition_id,
 subject_id,
 cohort_start_date,
 covariate_id,
 concept_count
FROM
(
 SELECT 
 CAST(visit_concept_id AS BIGINT) * 1000 + 923 AS covariate_id,
 cohort_definition_id,
 subject_id,
 cohort_start_date,
 COUNT(*) AS concept_count
 FROM @characterization_cohort cohort
 INNER JOIN @cdm_database_schema.visit_occurrence
 ON cohort.subject_id = visit_occurrence.person_id
 WHERE visit_start_date <= DATE_ADD(day,0,cohort.cohort_start_date)
 AND visit_end_date >= DATE_ADD(day,-365,cohort.cohort_start_date)
 AND visit_concept_id != 0
 GROUP BY 
 visit_concept_id,
 cohort_definition_id,
 subject_id,
 cohort_start_date
 ) raw_data;
