CREATE TABLE @temp_database_schema.rwdfeatxcov_8
USING DELTA
AS
SELECT
CAST(FLOOR((YEAR(cohort_start_date) - year_of_birth) / 5) * 1000 + 3 AS BIGINT) AS covariate_id,
 cohort_definition_id,
 COUNT(*) AS sum_value
FROM
@characterization_cohort cohort
INNER JOIN @cdm_database_schema.person
 ON cohort.subject_id = person.person_id
GROUP BY cohort_definition_id,
 FLOOR((YEAR(cohort_start_date) - year_of_birth) / 5)
;
INSERT INTO @temp_database_schema.rwdfeatxcov_ref (
 covariate_id,
 covariate_name,
 analysis_id,
 concept_id
 )
SELECT covariate_id,
 CAST(CONCAT (
 'age group: ',
 RIGHT(CONCAT(' ', CAST(CAST(5 * (covariate_id - 3) / 1000 AS INTEGER) AS STRING)), 3),
 ' - ',
 RIGHT(CONCAT(' ', CAST((CAST(5 * (covariate_id - 3) / 1000 AS INTEGER)) + 4 AS STRING)), 3)
 ) AS STRING) AS covariate_name,
 3 AS analysis_id,
 0 AS concept_id
FROM (
 SELECT DISTINCT covariate_id
 FROM @temp_database_schema.rwdfeatxcov_8
 ) t1;
INSERT INTO @temp_database_schema.rwdfeatxanalysis_ref (
 analysis_id,
 analysis_name,
 domain_id,
 start_day,
 end_day,
 is_binary,
 missing_means_zero
 )
SELECT 3 AS analysis_id,
 CAST('DemographicsAgeGroup' AS STRING) AS analysis_name,
 CAST('Demographics' AS STRING) AS domain_id,
 CAST(NULL AS INT) AS start_day,
 CAST(NULL AS INT) AS end_day,
 CAST('Y' AS STRING) AS is_binary,
 CAST(NULL AS STRING) AS missing_means_zero;
