DROP TABLE IF EXISTS @temp_database_schema.rwdfeatxdem_time_data;
DROP TABLE IF EXISTS @temp_database_schema.rwdfeatxdem_time_stats;
DROP TABLE IF EXISTS @temp_database_schema.rwdfeatxdem_time_prep;
DROP TABLE IF EXISTS @temp_database_schema.rwdfeatxdem_time_prep2;
CREATE TABLE @temp_database_schema.rwdfeatxdem_time_data
USING DELTA
AS
SELECT
subject_id,
 cohort_definition_id,
 cohort_start_date,
 days
FROM
(
 SELECT 
 cohort_definition_id,
 subject_id,
 cohort_start_date, 
 DATEDIFF(DAY, op.observation_period_start_date, cohort_start_date) AS days
 FROM @characterization_cohort cohort
 INNER JOIN @cdm_database_schema.observation_period op
 ON op.person_id = cohort.subject_id 
 AND op.observation_period_start_date <= cohort_start_date
 AND op.observation_period_end_date >= cohort_start_date
 ) raw_data;
DROP VIEW IF EXISTS t1  ; CREATE TEMPORARY VIEW t1   AS (SELECT cohort_definition_id,
 COUNT(*) AS cnt 
 FROM @characterization_cohort 
 GROUP BY cohort_definition_id
 );
DROP VIEW IF EXISTS t2 ; CREATE TEMPORARY VIEW t2  AS (SELECT cohort_definition_id,
 COUNT(*) AS cnt, 
 MIN(days) AS min_days, 
 MAX(days) AS max_days, 
 SUM(CAST(days AS BIGINT)) AS sum_days, 
 SUM(CAST(days AS BIGINT) * CAST(days AS BIGINT)) AS squared_days 
 FROM @temp_database_schema.rwdfeatxdem_time_data
 GROUP BY cohort_definition_id
 );
 CREATE TABLE @temp_database_schema.rwdfeatxdem_time_stats
USING DELTA
AS
(SELECT
t1.cohort_definition_id,
 CASE WHEN t2.cnt = t1.cnt THEN t2.min_days ELSE 0 END AS min_value,
 t2.max_days AS max_value,
 CAST(t2.sum_days / (1.0 * t1.cnt) AS FLOAT) AS average_value,
 CAST(CASE WHEN t2.cnt = 1 THEN 0 ELSE SQRT((1.0 * t2.cnt*t2.squared_days - 1.0 * t2.sum_days*t2.sum_days) / (1.0 * t2.cnt*(1.0 * t2.cnt - 1))) END AS FLOAT) AS standard_deviation,
 t2.cnt AS count_value,
 t1.cnt - t2.cnt AS count_no_value,
 t1.cnt AS population_size
FROM
t1
INNER JOIN t2
 ON t1.cohort_definition_id = t2.cohort_definition_id);
CREATE TABLE @temp_database_schema.rwdfeatxdem_time_prep
USING DELTA
AS
SELECT
cohort_definition_id,
 days,
 COUNT(*) AS total,
 ROW_NUMBER() OVER (PARTITION BY cohort_definition_id ORDER BY days) AS rn
FROM
@temp_database_schema.rwdfeatxdem_time_data
GROUP BY cohort_definition_id,
 days;
CREATE TABLE @temp_database_schema.rwdfeatxdem_time_prep2 
USING DELTA
AS
SELECT
s.cohort_definition_id,
 s.days,
 SUM(p.total) AS accumulated
FROM
@temp_database_schema.rwdfeatxdem_time_prep s
INNER JOIN @temp_database_schema.rwdfeatxdem_time_prep p
 ON p.rn <= s.rn
 AND p.cohort_definition_id = s.cohort_definition_id
GROUP BY s.cohort_definition_id,
 s.days;
CREATE TABLE @temp_database_schema.rwdfeatxcov_10
USING DELTA
AS
SELECT
o.cohort_definition_id,
 CAST(1000 + 8 AS BIGINT) AS covariate_id,
 o.count_value,
 o.min_value,
 o.max_value,
 CAST(o.average_value AS FLOAT) average_value,
 CAST(o.standard_deviation AS FLOAT) standard_deviation,
 CASE 
 WHEN .50 * o.population_size < count_no_value THEN 0
 ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .50 * o.population_size THEN days END) 
 END AS median_value,
 CASE 
 WHEN .10 * o.population_size < count_no_value THEN 0
 ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .10 * o.population_size THEN days END) 
 END AS p10_value, 
 CASE 
 WHEN .25 * o.population_size < count_no_value THEN 0
 ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .25 * o.population_size THEN days END) 
 END AS p25_value, 
 CASE 
 WHEN .75 * o.population_size < count_no_value THEN 0
 ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .75 * o.population_size THEN days END) 
 END AS p75_value, 
 CASE 
 WHEN .90 * o.population_size < count_no_value THEN 0
 ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .90 * o.population_size THEN days END) 
 END AS p90_value 
FROM
@temp_database_schema.rwdfeatxdem_time_prep2 p
INNER JOIN @temp_database_schema.rwdfeatxdem_time_stats o
 ON p.cohort_definition_id = o.cohort_definition_id
GROUP BY o.count_value,
 o.count_no_value,
 o.min_value,
 o.max_value,
 o.average_value,
 o.standard_deviation,
 o.population_size,
 o.cohort_definition_id;
